if(!s) throw new Error('slide-02 missing');
const before=s.html;
s.html=s.html
 .replace(/color:\s*#fff;\s*background:\s*#ff5c9a/g,'color:#1a1a1a;background:#ff5c9a')
 .replace(/color:\s*white;\s*background:\s*#ff5c9a/g,'color:#1a1a1a;background:#ff5c9a')
 .replace(/color:\s*#fff;\s*background:\s*#3a86ff/g,'color:#0f172a;background:#3a86ff')
