  s.html=s.html.replace(/(<span[^>]*style="[^"]*background:\s*#ff5c9a[^"]*)color:\s*(?:#fff|white)([^"]*"[^>]*>← 新值 5<\/span>)/i,'$1color:#1a1a1a$2')
